begin;
do $$ declare o uuid:='10000000-0000-4000-8000-000000000001'; site uuid:='10000000-0000-4000-8000-000000000002'; a uuid:=gen_random_uuid(); m uuid:=gen_random_uuid(); p uuid; ref uuid; imp uuid; doc uuid; c uuid; r text; result jsonb; rows jsonb; before_count integer; begin
insert into public.accounts(id,org_id,kind,synthetic) values(a,o,'staff',true); insert into public.staff_members(id,org_id,account_id,source_key,name,synthetic) values(m,o,a,'phase2_packet_test','Fictional Packet Tester',true); foreach r in array array['intake_coordinator','therapist'] loop insert into public.staff_role_assignments(org_id,staff_member_id,role) values(o,m,r); end loop;
execute format('create or replace function app.account_id() returns uuid language sql stable security definer set search_path='''' as %L','select '||quote_literal(a::text)||'::uuid'); perform app.attest_beta('en'); perform app.set_acting_role('intake_coordinator');
select count(*) into before_count from public.audit_events;
result:=app.phase2_run_action('intake_staging_import',null,jsonb_build_object('template_sha256',app.phase2_template_hash(),'source','pre_release_packet','source_ref','fictional-beta-packet-v1','first_name','Morgan','last_name','Beta Packet','dob','1990-04-12'),'fictional_packet'); ref:=(result->>'referral_id')::uuid; imp:=(result->>'id')::uuid;
if (select count(*) from public.audit_events)<>before_count+1 then raise exception 'import_audit_count'; end if;
if not exists(select 1 from public.staging_rows where import_id=imp and referral_id=ref) or (select count(*) from public.intake_packet_needs where referral_id=ref)<>2 then raise exception 'staging_source_flow'; end if;
result:=app.phase2_run_action('intake_packet_attach',ref,jsonb_build_object('type','medication_list','source','pre_release_packet','source_ref','fictional-beta-packet-v1','classification','part2','file_name','fictional-summary.txt'),'fictional_packet'); doc:=(result->>'id')::uuid;
rows:=app.packet_documents_view(ref); if jsonb_array_length(rows)<>1 or rows->0<>jsonb_build_object('id',doc,'locked',true,'reason','Part 2 — needs consent covering intake/treatment') then raise exception 'unlinked_packet_leak'; end if;
result:=app.phase2_run_action('phase2_referral_link',ref,jsonb_build_object('site_id',site),'fictional_verified_link'); p:=(result->>'id')::uuid;
if not exists(select 1 from public.referrals where id=ref and linked_patient_id=p) or not exists(select 1 from public.patient_site_enrollments where patient_id=p and site_id=site) then raise exception 'packet_patient_flow'; end if;
rows:=app.packet_documents_view(ref); if not (rows->0->>'locked')::boolean then raise exception 'no_consent_unlocked'; end if;
insert into public.consent_records(org_id,patient_id,consent_type,recipients,purpose_code,items,status,signed_by_kind,signature_method,part2_elements,effective_at,signed_at,synthetic) values(o,p,'part2_tpo_single','[{"kind":"class","name":"Adelante care team","directoryRef":"adelante-program"}]','tpo',array['Intake and treatment information'],'active','staff_capture','e_sign','{"patientName":true,"recipients":true,"amountAndKind":true,"purpose":true,"rightToRevoke":true,"expiration":true,"signatureAndDate":true,"redisclosureNotice":true}',now(),now(),true) returning id into c;
rows:=app.packet_documents_view(ref); if (rows->0->>'locked')::boolean then raise exception 'typed_consent_did_not_unlock'; end if;
if exists(select 1 from app.can_access('sud_treatment',p) where level<>'none') or exists(select 1 from app.can_access('screeners_sud',p) where level<>'none') or (app.chart_entry(p)->>'ok')::boolean then raise exception 'intake_consent_widened'; end if;
update public.consent_records set status='revoked' where id=c; rows:=app.packet_documents_view(ref); if not (rows->0->>'locked')::boolean then raise exception 'revocation_leak'; end if;
insert into public.staff_site_assignments(org_id,staff_member_id,site_id,starts_at,synthetic) values(o,m,site,now()-interval '1 day',true); perform app.set_acting_role('therapist'); if not (app.chart_entry(p)->>'ok')::boolean then raise exception 'same_site_chart_denied'; end if;
update public.staff_site_assignments set ends_at=now() where staff_member_id=m; if (app.chart_entry(p)->>'ok')::boolean then raise exception 'no_site_chart_allowed'; end if; update public.staff_site_assignments set ends_at=null where staff_member_id=m;
insert into public.restricted_record_flags(org_id,patient_id,reason_code,synthetic) values(o,p,'fictional_restriction',true); if (app.chart_entry(p)->>'searchable')::boolean or (app.chart_entry(p)->>'ok')::boolean then raise exception 'restricted_chart_leak'; end if;
perform app.set_acting_role('intake_coordinator'); if app.phase2_intake(ref,true) then raise exception 'restricted_packet_leak'; end if;
update public.acting_role_sessions set ended_at=now() where account_id=a and ended_at is null; if app.phase2_intake(ref,true) then raise exception 'null_role_leak'; end if;
end $$; rollback;